package com.mvt.backApp.config;import org.springframework.context.*;import org.springframework.context.annotation.*;import org.springframework.context.support.ReloadableResourceBundleMessageSource;import org.springframework.web.servlet.LocaleResolver;import org.springframework.web.servlet.i18n.AcceptHeaderLocaleResolver;import java.nio.charset.StandardCharsets;import java.util.*;@Configuration public class InternationalizationConfig{@Bean public LocaleResolver localeResolver(){AcceptHeaderLocaleResolver r=new AcceptHeaderLocaleResolver();r.setDefaultLocale(Locale.ENGLISH);r.setSupportedLocales(List.of(Locale.ENGLISH,Locale.FRENCH));return r;}@Bean public MessageSource messageSource(){ReloadableResourceBundleMessageSource s=new ReloadableResourceBundleMessageSource();s.setBasenames("classpath:messages","classpath:messages_password");s.setDefaultEncoding(StandardCharsets.UTF_8.name());s.setFallbackToSystemLocale(false);s.setDefaultLocale(Locale.ENGLISH);s.setUseCodeAsDefaultMessage(true);return s;}}
